from PIL import Image
import numpy as np
im=np.array(Image.open('input/drawing-enlarged.png').convert('RGB'))
def runs(y):
    row=im[y]; mask=(row[:,0]<220)|(row[:,1]<220)|(row[:,2]<220)
    xs=np.where(mask)[0]; xs=xs[(xs>=250)&(xs<=1050)]
    out=[]
    if len(xs):
        s=p=xs[0]
        for x in xs[1:]:
            if x>p+1:
                if p-s>5: out.append((s,p))
                s=x
            p=x
        if p-s>5: out.append((s,p))
    return out
for y in range(1060,1180,10):
    print(y,runs(y))
